<template>
  <section class="archive-assistant" data-testid="archive-assistant" aria-label="卷小助对话">
    <header class="assistant-heading"><strong>问助理</strong></header>
    <p v-if="state.historyLoading" class="assistant-note" role="status">正在恢复本案对话…</p>
    <p v-if="state.historyLimited" class="assistant-note">这里显示最近 100 次提问，更早记录仍保存在工作站。</p>
    <div v-if="state.historyError" class="assistant-error" role="alert" data-testid="assistant-history-error">{{ state.historyError }}<el-button data-testid="assistant-reload-history" text :disabled="state.pending||state.historyLoading" @click="conversation.reload()">重新读取记录</el-button></div>
    <details v-if="state.historyReady&&!state.messages.length&&!draftState.content" class="examples"><summary>试着问</summary><button v-for="example in examples" :key="example.message" :disabled="sendBlocked" @click="askExample(example.message)">{{ example.label }}</button></details>
    <div ref="conversationElement" class="conversation" aria-live="polite" aria-label="卷小助对话记录">
      <article v-for="message in state.messages" :key="message.id" class="message" :class="message.role">
        <span class="message-label">{{ message.role==='user'?'你':'卷小助' }}<template v-if="message.state==='failed'"> · 未完成</template><template v-else-if="message.state==='unknown'"> · 请求已中断，未自动重发</template><template v-else-if="message.state==='pending'"> · 正在处理</template><template v-if="message.revision&&message.revision!==revision"> · 较早草稿的记录</template></span><p class="message-text">{{ message.content }}</p><el-button v-if="message.role==='user'&&['failed','unknown'].includes(message.state)" data-testid="assistant-retry-question" text :disabled="sendBlocked" @click="askExample(message.content)">重新提问</el-button>
        <template v-if="message.role==='assistant'">
          <div v-for="(item,index) in message.items" :key="index" class="result-item"><strong>{{ item.title }}</strong><p v-if="item.text">{{ item.text }}</p><button v-if="item.file_id&&item.page" class="result-link" @click="emit('source',{...item,filename:item.title})">打开原文页</button><button v-else-if="item.field" class="result-link" @click="emit('field',item.field)">查看字段依据</button></div>
          <div v-if="message.proposal" class="proposal-card" data-testid="assistant-proposal"><div class="proposal-heading"><strong>{{ message.proposal.field }}</strong><span>{{ proposalApplied(message.proposal)?'修改建议 · 已采用':message.proposal.state==='applying'?'修改建议 · 采用待恢复':'修改建议 · 尚未采用' }}</span></div><div class="proposal-comparison"><div><span>原值</span><p>{{ message.proposal.before||'空白' }}</p></div><div><span>修改为</span><p>{{ message.proposal.after||'留空' }}</p></div></div><p class="proposal-note">{{ message.proposal.reason }}</p><p v-if="proposalApplied(message.proposal)" class="proposal-applied" role="status">已写入草稿，最终归档仍需确认。</p><template v-else-if="message.proposal.state==='applying'"><p class="proposal-error" data-testid="proposal-recovery-notice">{{ message.proposal.notice||'上次采用尚未确认完成。可先恢复状态，再核对是否采用；此操作不会自动采用修改。' }}</p><el-button data-testid="recover-assistant-proposal" plain :loading="proposalState[message.proposal.id]?.pending" :disabled="busy||recoverDisabled||state.pending||state.serverPending" @click="recoverProposal(message.proposal)">恢复采用状态（不自动采用）</el-button></template><p v-else-if="staleProposal(message.proposal)" class="proposal-error">这条建议已过期或草稿已有变化。请重新告诉我需要修改的内容。</p><p v-if="proposalState[message.proposal.id]?.error" class="proposal-error" role="alert">{{ proposalState[message.proposal.id].error }}</p><el-button v-if="!proposalApplied(message.proposal)&&message.proposal.state!=='applying'" data-testid="apply-assistant-proposal" type="primary" plain :loading="proposalState[message.proposal.id]?.pending" :disabled="busy||writeDisabled||state.pending||state.serverPending||state.historyLoading||!state.historyReady||staleProposal(message.proposal)" @click="applyProposal(message.proposal)">采用修改</el-button></div>
          <el-button v-if="message.action" class="action-button" text @click="emit('action',message.action.type)">{{ message.action.label }}</el-button>
        </template>
      </article>
      <p v-if="state.pending" class="assistant-note" role="status">{{ mode==='deepseek_cloud'?'正在通过 DeepSeek 核对本案资料…':'正在核对本案资料…' }}</p>
    </div>
    <p v-if="state.serverPending" class="assistant-note" role="status" data-testid="assistant-restored-pending">之前的提问正在处理，正在读取回复，不会重复调用模型。</p>
    <p v-if="state.error" class="assistant-error" role="alert">{{ state.error }}</p>
    <p v-if="shortcutNotice" class="assistant-note" data-testid="assistant-shortcut-notice">{{ shortcutNotice }}</p>
    <div v-if="draftStatusVisible" class="assistant-draft-status" data-testid="assistant-draft-status" aria-live="polite">
      <p v-if="draftState.loading">正在读取工作站中的未发送草稿…</p>
      <p v-else-if="draftReadOnly||!draftState.writable">{{ draftState.notice||'此任务的未发送草稿仅供查看，不能继续编辑或发送。' }}</p>
      <p v-else-if="draftState.sending">正在发送，仍可写下新要求；发送中的文字不会作为新草稿重复提交。</p>
      <p v-else-if="draftState.saving">正在同步到工作站…</p>
      <p v-else-if="draftState.dirty">本机有未同步文字，离开前请完成同步或明确放弃。</p>
      <p v-else-if="draftState.loaded">已同步到工作站</p>
      <p v-if="draftState.error" class="assistant-error" role="alert">{{ draftState.error }}</p>
      <div v-if="draftState.conflict" data-testid="assistant-draft-conflict"><p>本机文字：</p><p class="message-text">{{ draftState.content||'空白' }}</p><template v-if="draftState.remote"><p>工作站文字：</p><p class="message-text">{{ draftState.remote.content||'空白' }}</p><el-button data-testid="draft-keep-local" :disabled="draftReadOnly||!draftState.writable||draftState.loading" @click="drafts.chooseLocal()">保留本机，继续同步</el-button><el-button data-testid="draft-use-remote" :disabled="draftState.loading" @click="drafts.useRemote()">使用工作站草稿</el-button></template></div>
      <p v-if="draftState.contextChanged" data-testid="assistant-draft-old-context">这份文字基于较早的案件版本。核对后可明确继续用于当前版本。<el-button data-testid="draft-continue-context" :disabled="draftReadOnly||!draftState.writable||draftState.conflict||draftState.loading" @click="drafts.continueCurrentContext()">继续编辑当前版本</el-button></p>
      <el-button v-if="draftState.error||draftState.conflict&&!draftState.remote" data-testid="draft-reload" text :disabled="draftState.loading||draftState.saving||draftState.sending" @click="drafts.reload()">重新读取工作站草稿</el-button>
      <el-button v-if="draftState.dirty&&!draftState.conflict&&!draftState.contextChanged&&draftState.loaded" data-testid="draft-sync" text :disabled="draftReadOnly||!draftState.writable||draftState.saving||draftState.sending||draftState.loading" @click="drafts.flush()">重试同步</el-button>
    </div>
    <form class="assistant-composer" @submit.prevent="submit"><el-input :model-value="draftState.content" @update:model-value="drafts.edit" :disabled="draftReadOnly||!draftState.writable||(draftState.loading&&!draftState.loaded&&!draftState.error)" data-testid="assistant-question" type="textarea" :rows="2" maxlength="1500" aria-label="给卷小助的要求" placeholder="提问，或告诉我需要修改的内容…" /><div class="send-row"><span>{{ busy?'整理中，可先写下要求':'修改需由你确认' }}</span><el-button data-testid="assistant-send" type="primary" native-type="submit" :loading="state.pending" :disabled="sendBlocked||!draftState.content.trim()">发送 <span aria-hidden="true">↑</span></el-button></div></form>
  </section>
</template>
<script setup lang="ts">
import { ref,computed,watch,nextTick,onMounted,onUnmounted } from 'vue'
import client from '../api/client'
import { createAssistantConversation } from '../domain/assistant.js'
import { createAssistantDraft } from '../domain/assistantDraft.js'
import { createRequestId } from '../domain/workflow.js'
import { createProposalApplication,proposalIsStale } from '../domain/assistantProposal.js'
const props=defineProps<{taskId:string,accountScope?:string,draftReadOnly?:boolean,busy?:boolean,mode?:string,revision?:number,sourceVersion?:string,writeDisabled?:boolean,recoverDisabled?:boolean,beforeApply?:(revision:number)=>Promise<string>,beforeRecover?:(revision:number)=>Promise<string>}>()
const emit=defineEmits<{source:[entry:any],field:[name:string],action:[type:string],applied:[task:any],busy:[value:boolean],draftDirty:[value:boolean],refresh:[]}>()
const draftState=ref<any>({content:'',loaded:false,loading:true,writable:true,dirty:false}),state=ref<any>({messages:[],pending:false,error:''}),proposalState=ref<any>({}),conversationElement=ref<HTMLElement|null>(null)
const shortcutNotice=ref('')
const draftStatusVisible=computed(()=>draftState.value.content||draftState.value.loading||draftState.value.saving||draftState.value.sending||draftState.value.error||draftState.value.conflict||draftState.value.contextChanged||props.draftReadOnly||!draftState.value.writable)
const proposalPending=computed(()=>Object.values(proposalState.value).some((item:any)=>item.pending))
const sendBlocked=computed(()=>props.busy||proposalPending.value||state.value.pending||state.value.historyLoading||!state.value.historyReady||state.value.serverPending||props.draftReadOnly||!draftState.value.writable||!draftState.value.loaded||draftState.value.loading||draftState.value.conflict||draftState.value.contextChanged||draftState.value.unknown)
const examples=[{label:'还缺哪些材料',message:'还缺哪些材料？'},{label:'案号从哪里来',message:'案号这个字段从哪里来？'},{label:'核对当前草稿',message:'这份归档草稿有哪些需要注意的地方？'}]
const conversation=createAssistantConversation({readHistory:async(taskId:string,signal:AbortSignal)=>(await client.get('/tasks/'+encodeURIComponent(taskId)+'/assistant/history',{signal})).data,getContext:()=>({revision:props.revision,source_version:props.sourceVersion}),request:async(taskId:string,payload:any,signal:AbortSignal)=>(await client.post('/tasks/'+encodeURIComponent(taskId)+'/assistant',payload,{signal})).data,onChange:(value:any)=>{state.value=value;nextTick(()=>{const element=conversationElement.value;if(element)element.scrollTop=element.scrollHeight})}})
const proposals=createProposalApplication({request:async(id:string,body:any,signal:AbortSignal)=>(await client.post('/tasks/'+encodeURIComponent(id)+'/assistant/proposals/apply',body,{signal})).data,beforeApply:(revision:number)=>props.beforeApply?props.beforeApply(revision):Promise.resolve('请返回当前任务后采用修改。'),beforeRecover:(revision:number)=>props.beforeRecover?props.beforeRecover(revision):Promise.resolve('请返回当前任务后恢复采用状态。'),onChange:(value:any)=>{proposalState.value=value;emit('busy',Object.values(value).some((item:any)=>item.pending))},onApplied:(task:any)=>emit('applied',task),onRecovered:()=>{emit('refresh');conversation.reload()},onUncertain:async()=>{emit('refresh');await conversation.reload()}})
const drafts=createAssistantDraft({read:async(id:string,signal:AbortSignal)=>(await client.get('/tasks/'+encodeURIComponent(id)+'/assistant/draft',{signal})).data,write:async(id:string,body:any,signal:AbortSignal)=>(await client.put('/tasks/'+encodeURIComponent(id)+'/assistant/draft',body,{signal})).data,getContext:()=>({revision:props.revision,source_version:props.sourceVersion,readOnly:props.draftReadOnly}),onChange:(value:any)=>{draftState.value=value;emit('draftDirty',value.dirty)}})
watch(()=>[props.taskId,props.accountScope],()=>{shortcutNotice.value='';conversation.reset(props.taskId);proposals.reset();drafts.reset(props.taskId)},{immediate:true})
watch(()=>[props.revision,props.sourceVersion,props.draftReadOnly],()=>drafts.updateContext())
function staleProposal(proposal:any){return proposalState.value[proposal.id]?.stale||proposalIsStale(proposal,props.revision,props.sourceVersion)}
function proposalApplied(proposal:any){return proposal.state==='applied'||proposalState.value[proposal.id]?.applied}
function applyProposal(proposal:any){return proposals.apply(props.taskId,proposal,{revision:props.revision,sourceVersion:props.sourceVersion,disabled:props.busy||props.writeDisabled||state.value.pending||state.value.serverPending||state.value.historyLoading||!state.value.historyReady})}
function recoverProposal(proposal:any){return proposals.recover(props.taskId,proposal,{revision:props.revision,disabled:props.busy||props.recoverDisabled||state.value.pending||state.value.serverPending})}
async function submit(){if(sendBlocked.value)return;if(!(await drafts.flush())||sendBlocked.value)return;const saved=drafts.snapshot();if(!saved)return;let requestId;try{requestId=createRequestId()}catch(error:any){draftState.value={...draftState.value,error:error.message};return}const sent=drafts.beginSend(saved,requestId);if(!sent)return;try{await conversation.ask(sent.content,{requestId,draftVersion:sent.version})}finally{await drafts.finishSend(sent)}}
function askExample(question:string){if(sendBlocked.value)return;if(draftState.value.content&&draftState.value.content!==question){shortcutNotice.value='当前已有未发送文字，请先处理当前草稿，再重新提问。';return}shortcutNotice.value='';if(!draftState.value.content)drafts.edit(question);submit()}
let historyPoll:ReturnType<typeof setInterval>|null=null
onMounted(()=>{historyPoll=setInterval(()=>{if(state.value.serverPending&&!state.value.historyLoading&&!state.value.pending)conversation.reload()},5000)})
onUnmounted(()=>{if(historyPoll)clearInterval(historyPoll);conversation.dispose();proposals.reset();drafts.dispose()})
</script>
<style scoped>
.archive-assistant{margin:30px 0 10px;color:#424245;font-size:12px;line-height:1.8}.assistant-heading{display:flex;gap:11px;align-items:center;margin-bottom:15px}.assistant-avatar{display:grid;place-items:center;width:30px;height:30px;background:#e5e5ea;color:#424245;border-radius:10px;font-family:Georgia,serif;font-size:12px}.assistant-heading strong{font-size:12px;font-weight:500}.assistant-heading p{margin:2px 0 0;font-size:10px;color:#6e6e73}.examples{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0 18px}.examples button{border:1px solid #e5e5ea;border-radius:20px;background:#fff;padding:6px 12px;font-size:11px;color:#6e6e73;cursor:pointer}.examples button:disabled{opacity:.5;cursor:wait}.conversation{max-height:520px;overflow:auto;overscroll-behavior:contain;scrollbar-width:thin}.message{padding:14px 0;margin:8px 0}.message.user{background:#f5f5f7;border-radius:12px;padding:14px 18px;margin-left:12%}.message-label{font-size:10px;color:#6e6e73}.message-text{white-space:pre-wrap;overflow-wrap:anywhere;margin:6px 0 0;font-size:13px;line-height:1.95;color:#424245}.result-item{padding:10px 0;border-bottom:1px solid #f5f5f7;font-size:11px;overflow-wrap:anywhere}.result-item strong{font-weight:500}.result-item p{white-space:pre-wrap;margin:6px 0;color:#6e6e73}.result-link{border:0;background:none;padding:5px 0;color:#424245;font-size:11px;cursor:pointer;text-decoration:underline}.assistant-composer{border:1px solid #e5e5ea;background:white;border-radius:13px;padding:12px 14px;margin-top:18px;box-shadow:0 4px 20px #1d1d1f05}.assistant-composer :deep(.el-textarea__inner){box-shadow:none;resize:none;padding:2px 0;background:transparent;font-size:12px;line-height:1.8}.send-row{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-top:12px}.send-row>span{font-size:10px;color:#6e6e73;line-height:1.7}.send-row .el-button{height:32px;font-size:12px}.send-row .el-button span[aria-hidden]{margin-left:8px}.assistant-note,.assistant-error{font-size:11px;white-space:pre-wrap;line-height:1.9;margin:12px 0}.assistant-note{color:#6e6e73}.assistant-error{color:#a8755a}.proposal-card{border:1px solid #e5e5ea;border-radius:10px;padding:16px;margin-top:16px;background:#fafafa}.proposal-heading{display:flex;justify-content:space-between;gap:10px}.proposal-heading strong{font-weight:500}.proposal-heading span,.proposal-note{font-size:10px;color:#6e6e73}.proposal-comparison{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-top:15px}.proposal-comparison>div{padding:12px;background:white;border:1px solid #e5e5ea;border-radius:6px}.proposal-comparison span{font-size:10px;color:#6e6e73}.proposal-comparison p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9;margin:5px 0;font-size:12px}.proposal-error{font-size:11px;color:#a67b57}.proposal-applied{font-size:11px;color:#424245}.action-button{margin-top:6px}@media(max-width:600px){.proposal-comparison{grid-template-columns:1fr}.send-row{align-items:flex-end}.send-row .el-button{flex:none}}
</style>

